package com.futahua.papers.mobile;
import android.app.*;import android.os.*;import org.json.*;import java.io.*;import java.util.*;
public final class PhoneTransferEditingCheck extends Instrumentation {
 private int passed;private void check(boolean value,String label)throws Exception{if(!value)throw new IOException(label);passed++;Bundle b=new Bundle();b.putString("check",label);b.putInt("passed",passed);sendStatus(1,b);}
 private void put(File file,String text)throws Exception{try(FileOutputStream out=new FileOutputStream(file)){out.write(text.getBytes("UTF-8"));out.getFD().sync();}}
 private void clean(File file){if(file.isDirectory()){File[] children=file.listFiles();if(children!=null)for(File child:children)clean(child);}file.delete();}
 @Override public void onCreate(Bundle args){start();}
 @Override public void onStart(){Bundle result=new Bundle();int code=Activity.RESULT_OK;File disk=new File(Environment.getExternalStorageDirectory(),"Download/PapersTransferCheck-"+UUID.randomUUID()),privateRoot=new File(getTargetContext().getFilesDir(),"transfer-check-"+UUID.randomUUID());
 try{if(!disk.mkdirs())throw new IOException("Fixture unavailable");privateRoot.mkdirs();File file=new File(disk,"original.txt");put(file,"original");String resource=UUID.randomUUID().toString();
  PhoneFileEdits.Catalog catalog=new PhoneFileEdits.Catalog(){public File resolve(String id)throws Exception{if(!id.equals(resource))throw new IOException("Unshared");return file;}public JSONObject entry(File f)throws Exception{if(!f.getCanonicalFile().equals(file.getCanonicalFile())||!f.isFile())throw new IOException("Unshared");return new JSONObject().put("id",resource).put("name",f.getName()).put("kind","file").put("size",f.length()).put("modifiedAt",f.lastModified()).put("version",PhonePeerServer.hash((f.length()+"|"+f.lastModified()+"|"+MobileEditCopies.digest(f)).getBytes("UTF-8")));}};
  Object lock=new Object();PhoneFileEdits owner=new PhoneFileEdits(getTargetContext(),lock,privateRoot);JSONArray editors=new JSONArray().put(new JSONObject().put("id","editor").put("name","Editor"));JSONObject source=catalog.entry(file),assign=owner.assignment("controller",new JSONObject().put("resourceId",resource).put("sourceVersion",source.getString("version")).put("editorDeviceId","editor"),catalog,editors);
  check(!assign.has("path")&&assign.optBoolean("active"),"assignment is explicit and owner paths stay private");
  JSONObject session=owner.begin("editor",new JSONObject().put("resourceId",resource).put("sourceVersion",source.getString("version")),catalog);check(session.getString("assignmentId").equals(assign.getString("id")),"chosen editor receives the checked assignment");
  byte[] bytes="edited snapshot".getBytes("UTF-8");String sha=PhonePeerServer.hash(bytes),upload=owner.beginUpload("editor",session.getString("id"),new JSONObject().put("bytes",bytes.length).put("sha256",sha)).getString("uploadId");owner.append("editor",upload,0,4,new ByteArrayInputStream(Arrays.copyOfRange(bytes,0,4)));
  check(owner.uploadStatus("editor",upload).getLong("receivedBytes")==4,"mature Java tus engine retains a partial upload on Android");
  owner=new PhoneFileEdits(getTargetContext(),lock,privateRoot);check(owner.uploadStatus("editor",upload).getLong("receivedBytes")==4,"partial edit survives owner restart");owner.append("editor",upload,4,bytes.length-4,new ByteArrayInputStream(Arrays.copyOfRange(bytes,4,bytes.length)));owner.seal("editor",upload);
  String save=UUID.randomUUID().toString();JSONObject request=new JSONObject().put("saveId",save).put("uploadId",upload).put("sha256",sha),saved=owner.save("editor",session.getString("id"),request,catalog);check(saved.getString("phase").equals("saved")&&MobileEditCopies.digest(file).equals(sha),"verified edited snapshot replaces the exact phone original");
  owner=new PhoneFileEdits(getTargetContext(),lock,privateRoot);check(owner.save("editor",session.getString("id"),request,catalog).getString("phase").equals("saved"),"lost save reply is recovered from the retained receipt");
  JSONObject next=owner.begin("editor",new JSONObject().put("resourceId",resource).put("sourceVersion",catalog.entry(file).getString("version")),catalog);owner.assignment("third-device",new JSONObject().put("action","stop").put("id",assign.getString("id")),catalog,editors);
  boolean refused=false;try{owner.beginUpload("editor",next.getString("id"),new JSONObject().put("bytes",bytes.length).put("sha256",sha));}catch(Exception expected){refused=true;}check(refused&&MobileEditCopies.digest(file).equals(sha),"third-device stop fences delayed writes and keeps the disk version");
  result.putInt("passed",passed);
 }catch(Throwable error){code=Activity.RESULT_CANCELED;result.putString("error",error.toString());result.putInt("passed",passed);android.util.Log.e("PapersTransferCheck","Failure",error);}finally{if(disk.getName().startsWith("PapersTransferCheck-"))clean(disk);if(privateRoot.getName().startsWith("transfer-check-"))clean(privateRoot);}finish(code,result);}
}
